"use client";

import * as React from "react";
import { CodeInput } from "./code-input";
import { Coo, type CooHandle } from "./coo-pigeon";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";
import {
  EASE_OUT,
  useInteractionReducedMotion,
} from "./imported-ui-interaction-motion";

/* ─────────────────────────────────────────────────────────
 * VERIFY CODE: the pigeon who carried it
 *
 *   waiting  Coo stands on his post across the stage from the
 *            mailbox; its flag is up, your code is in there
 *   reading  every digit you type, he nods along
 *   wrong    he shakes his head; the boxes shake and clear
 *   right    the boxes close into one pill, he puffs his chest
 *            and gives two proud flaps
 *   wait     while the resend clock runs he naps on his post,
 *            z's drifting up and a thought bubble counting the
 *            seconds down; typing wakes him to read along, and
 *            at zero the bubble pops and he hops up, ready
 *   resend   he takes off with a new envelope, flies the route,
 *            pops the mailbox flag and flies home; if the send
 *            fails he comes back with the envelope in his beak
 *
 * onVerify gets the code, onResend sends another; both are
 * yours, whatever sends your codes.
 * ───────────────────────────────────────────────────────── */

export interface VerifyCodeProps {
  /** Where the code went: an email address or a phone number. */
  destination: string;
  channel?: "email" | "sms";
  length?: number;
  /** Check the code. Resolve (or return true) to accept; return false or throw to say it's wrong. */
  onVerify: (code: string) => Promise<boolean | void>;
  /** Send a new code. Return { retryAfter } (seconds) to set the next wait; throw to say it didn't go. */
  onResend: () => Promise<{ retryAfter?: number } | void | unknown>;
  /** Seconds before the first resend. */
  resendAfter?: number;
  /** Shows Change beside the address. */
  onChangeDestination?: () => void;
  title?: string;
  /** What the pigeon is called in his lines. */
  name?: string;
  autoFocus?: boolean;
  className?: string;
}

const mix = (color: string, amount: number, into = "transparent") =>
  `color-mix(in oklab, ${color} ${amount}%, ${into})`;
const PF = "var(--primary-foreground)";
const CARD: React.CSSProperties = {
  backgroundImage: `linear-gradient(180deg, var(--card), ${mix("var(--card)", 95, "var(--foreground)")})`,
  boxShadow: `0 0 0 1px var(--border), inset 0 1px 0 ${mix("var(--background)", 85)}`,
};
/* The one lit surface, ruled with faint airmail stripes along its foot: the sky he flies through. */
const STAGE: React.CSSProperties = {
  backgroundColor: "var(--primary)",
  backgroundImage: [
    `radial-gradient(90% 70% at 50% 0%, ${mix(PF, 20)} 0%, transparent 62%)`,
    `linear-gradient(175deg, transparent 45%, ${mix("black", 20)} 100%)`,
    `repeating-linear-gradient(-45deg, ${mix(PF, 10)} 0 7px, transparent 7px 14px, ${mix(PF, 5)} 14px 21px, transparent 21px 28px)`,
  ].join(", "),
  backgroundSize: "auto, auto, 100% 7px",
  backgroundRepeat: "no-repeat, no-repeat, repeat-x",
  backgroundPosition: "0 0, 0 0, 0 100%",
  boxShadow: `inset 0 1px 0 ${mix(PF, 36)}, inset 0 0 0 1px ${mix(PF, 12)}`,
};
const COO = {
  "--coo-route": PF,
  "--coo-z": PF,
  "--coo-bubble": PF,
  "--coo-bubble-ink": "var(--primary)",
} as React.CSSProperties;

type Flight = "home" | "away" | "failed";

export function VerifyCode({
  destination,
  channel = "email",
  length = 6,
  onVerify,
  onResend,
  resendAfter = 30,
  onChangeDestination,
  title,
  name = "Coo",
  autoFocus,
  className = "",
}: VerifyCodeProps) {
  const reduced = useInteractionReducedMotion();
  const baseId = React.useId();
  const coo = React.useRef<CooHandle>(null);
  const [phase, setPhase] = React.useState<
    "idle" | "checking" | "wrong" | "right"
  >("idle");
  const [left, setLeft] = React.useState(resendAfter);
  const [send, setSend] = React.useState<ActionStatus>("idle");
  const [flight, setFlight] = React.useState<Flight>("home");
  const typed = React.useRef(0);
  // typing wakes him for a while; then he nods off again if the clock is still running
  const [awake, setAwake] = React.useState(false);
  const awakeTimer = React.useRef(0);
  React.useEffect(() => () => window.clearTimeout(awakeTimer.current), []);

  // whole seconds down to zero; the route drains with them
  React.useEffect(() => {
    if (left <= 0 || flight === "away") return;
    const timer = window.setTimeout(
      () => setLeft((s) => Math.max(0, s - 1)),
      1000,
    );
    return () => window.clearTimeout(timer);
  }, [left, flight]);

  const resend = async () => {
    if (send === "pending" || left > 0 || flight === "away") return;
    setSend("pending");
    setFlight("away");
    coo.current?.send();
    let next = resendAfter;
    let ok = true;
    try {
      const res = await onResend();
      const after = (res as { retryAfter?: number } | undefined)?.retryAfter;
      if (typeof after === "number" && after >= 0) next = after;
    } catch {
      ok = false;
    }
    const home = () => {
      setFlight(ok ? "home" : "failed");
      setSend(ok ? "success" : "error");
      if (ok) {
        setLeft(next);
      }
      window.setTimeout(
        () => setSend((s) => (s === "success" ? "idle" : s)),
        1400,
      );
    };
    if (coo.current) coo.current.delivered(ok, home);
    else home();
  };

  const verify = async (code: string) => {
    setPhase("checking");
    let ok = false;
    try {
      ok = (await onVerify(code)) !== false;
    } catch {
      ok = false;
    }
    setPhase(ok ? "right" : "wrong");
    if (ok) coo.current?.puff();
    else coo.current?.ruffle();
    return ok;
  };

  const where = channel === "sms" ? "number" : "inbox";
  const mood =
    phase === "right"
      ? "Signed for. You’re in."
      : phase === "wrong"
        ? `Not the code ${name} carried`
        : phase === "checking"
          ? `${name} is checking`
          : flight === "away"
            ? `${name} is on his way`
            : flight === "failed"
              ? `${name} couldn’t get through`
              : send === "success"
                ? "A fresh code, delivered"
                : left > 0
                  ? awake
                    ? `${name} is reading along`
                    : `${name} is catching his breath`
                  : `${name} is ready to fly again`;
  const ready = left <= 0 && flight !== "away";

  return (
    <section
      aria-labelledby={`${baseId}-title`}
      className={`relative w-full max-w-[380px] rounded-[28px] p-2 text-card-foreground ${className}`}
      style={{ ...CARD, ...COO }}
    >
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 380px)" }}
      />
      <div className="@container w-full">
        <div
          className="relative overflow-clip rounded-[22px] text-primary-foreground"
          style={STAGE}
        >
          <Coo
            ref={coo}
            wait={flight === "away" || phase === "right" ? 0 : left}
            dozing={
              !awake &&
              flight === "home" &&
              (phase === "idle" || phase === "wrong")
            }
            reduced={reduced}
          />
          <p className="absolute inset-x-0 bottom-3 z-10 text-center text-[12.5px] font-medium text-primary-foreground/85 @max-[340px]:bottom-2 @max-[340px]:text-[11.5px]">
            <TextMorph>{mood}</TextMorph>
          </p>
        </div>

        <div className="px-3 pb-2 pt-3">
          <h2
            id={`${baseId}-title`}
            className="text-[15px] font-medium tracking-[-0.01em]"
          >
            {title ?? `Check your ${where}`}
          </h2>
          <p className="mt-0.5 text-[12.5px] text-muted-foreground">
            {name} brought a {length}-digit code to{" "}
            <span className="font-medium text-foreground">{destination}</span>
            {onChangeDestination ? (
              <>
                {" · "}
                <button
                  type="button"
                  onClick={onChangeDestination}
                  className="cursor-pointer underline decoration-border underline-offset-2 hover:text-foreground"
                >
                  Change
                </button>
              </>
            ) : (
              "."
            )}
          </p>

          <CodeInput
            className="mt-3"
            length={length}
            label="Enter the code"
            autoFocus={autoFocus}
            onValueChange={(v) => {
              setAwake(true);
              window.clearTimeout(awakeTimer.current);
              awakeTimer.current = window.setTimeout(
                () => setAwake(false),
                4000,
              );
              if (v.length > typed.current) coo.current?.peck();
              typed.current = v.length;
              if (phase === "wrong") setPhase("idle");
            }}
            onComplete={verify}
          />

          {/* the resend line folds away once the code is right */}
          <div
            className="grid"
            style={{
              gridTemplateRows: phase === "right" ? "0fr" : "1fr",
              opacity: phase === "right" ? 0 : 1,
              transition: reduced
                ? "none"
                : `grid-template-rows 420ms ${EASE_OUT}, opacity 240ms`,
            }}
          >
            <div className="min-w-0 overflow-hidden" inert={phase === "right"}>
              <div className="mt-2.5 flex h-7 items-center gap-1.5 text-[12px] text-muted-foreground">
                <span>
                  {flight === "failed"
                    ? "Couldn’t send that."
                    : "Didn’t get it?"}
                </span>
                <span className="grid items-center">
                  <span className="sr-only">
                    {ready
                      ? ""
                      : flight === "away"
                        ? "Sending a new code."
                        : "You can resend the code shortly."}
                  </span>
                  <span
                    aria-hidden="true"
                    className="col-start-1 row-start-1 flex items-baseline whitespace-nowrap tabular-nums"
                    style={{
                      opacity: ready ? 0 : 1,
                      filter: ready ? "blur(3px)" : "none",
                      transition: reduced
                        ? "none"
                        : `opacity 260ms ${EASE_OUT}, filter 260ms ${EASE_OUT}`,
                    }}
                  >
                    {flight === "away" ? (
                      <TextMorph>Sending</TextMorph>
                    ) : (
                      <>
                        Resend in {Math.floor(left / 60)}:
                        <NumberRoll
                          value={left % 60}
                          format={{ minimumIntegerDigits: 2 }}
                          direction="down"
                          duration={700}
                        />
                      </>
                    )}
                  </span>
                  <span
                    className="col-start-1 row-start-1"
                    inert={!ready}
                    style={{
                      opacity: ready ? 1 : 0,
                      filter: ready ? "none" : "blur(3px)",
                      transition: reduced
                        ? "none"
                        : `opacity 260ms ${EASE_OUT}, filter 260ms ${EASE_OUT}`,
                    }}
                  >
                    <StatusButton
                      variant="ghost"
                      size="sm"
                      status={send === "pending" ? "idle" : send}
                      labels={{
                        idle: "Resend code",
                        success: "Sent",
                        error: "Try again",
                      }}
                      onClick={resend}
                      className="-ml-2"
                    />
                  </span>
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

export default VerifyCode;

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CODE INPUT: the six boxes, done properly
 *
 *   typing     each digit rises into its box out of a blur; the
 *              box you're on carries a blinking caret; deleting
 *              lifts a digit away rather than blinking it out
 *   paste      a pasted or autofilled code drops in one box after
 *              another
 *   checking   with every box full, the row carries a sweep of
 *              light while onComplete runs
 *   wrong      the row shakes, the boxes turn red, the label
 *              says so, and the digits clear from the right
 *   right      the digits stay where they are while the boxes'
 *              own outlines melt into one pill around them; a
 *              check draws itself at its end, "Verified"
 *   resend     "Resend in 0:28", the seconds rolling down, then
 *              a Resend button that spins, ticks and starts the
 *              clock again
 *
 * One real input sits over the boxes (one-time-code autofill,
 * paste and the numeric keyboard all just work); the boxes are
 * only what you see.
 * ───────────────────────────────────────────────────────── */

export interface CodeInputProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> {
  length?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Runs when every box is filled. Resolve (or return true) to accept; throw or return false to reject. */
  onComplete?: (code: string) => Promise<boolean | void> | boolean | void;
  /** Shows the resend line; the clock starts on mount and after each resend. */
  onResend?: () => Promise<unknown> | void;
  /** Seconds before a code can be resent. */
  resendAfter?: number;
  label?: string;
  /** Box groups, e.g. [3, 3] puts a dash between two threes. */
  groups?: number[];
  /** Letters as well as digits. */
  alphanumeric?: boolean;
  autoFocus?: boolean;
}

type Phase = "idle" | "checking" | "wrong" | "right";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SHEEN =
  "[mask-image:linear-gradient(90deg,rgb(0_0_0/0.4)_35%,#000_50%,rgb(0_0_0/0.4)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none]";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** One character: rises in out of a blur when it arrives, lifts away when it goes. */
function Glyph({
  char,
  delay,
  reduced,
}: {
  char: string | undefined;
  delay: number;
  reduced: boolean;
}) {
  const [shown, setShown] = React.useState(char);
  const [leaving, setLeaving] = React.useState(false);
  const ref = React.useRef<HTMLSpanElement>(null);
  // The character last drawn rising in: the one there on mount never rises, a new one always does.
  const risen = React.useRef(char);
  if (char !== undefined && (char !== shown || leaving)) {
    setShown(char);
    setLeaving(false);
  } else if (
    char === undefined &&
    shown !== undefined &&
    (!leaving || reduced)
  ) {
    // With reduced motion a character just goes; otherwise it lifts away first.
    if (reduced) {
      setShown(undefined);
      setLeaving(false);
    } else setLeaving(true);
  }

  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced) return;
    if (leaving) {
      const a = el.animate(
        [
          { opacity: 1, transform: "none", filter: "blur(0px)" },
          { opacity: 0, transform: "translateY(-35%)", filter: "blur(4px)" },
        ],
        { duration: 200, delay, easing: EASE, fill: "forwards" },
      );
      a.onfinish = () => setShown(undefined);
      return () => a.cancel();
    }
    if (shown === undefined) {
      risen.current = undefined;
      return;
    }
    if (risen.current === shown) return;
    risen.current = shown;
    const a = el.animate(
      [
        { opacity: 0, transform: "translateY(45%)", filter: "blur(4px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 300, delay, easing: EASE, fill: "backwards" },
    );
    return () => a.cancel();
  }, [shown, leaving]);

  if (shown === undefined) return null;
  return (
    <span ref={ref} className="inline-block">
      {shown}
    </span>
  );
}

export function CodeInput({
  length = 6,
  value,
  defaultValue = "",
  onValueChange,
  onComplete,
  onResend,
  resendAfter = 30,
  label = `Enter the ${length}-digit code`,
  groups,
  alphanumeric = false,
  autoFocus,
  className = "",
  ...props
}: CodeInputProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(defaultValue.slice(0, length));
  const code = (value ?? own).slice(0, length);
  const [phase, setPhase] = React.useState<Phase>("idle");
  const [focused, setFocused] = React.useState(false);
  const [arrival, setArrival] = React.useState({
    length: code.length,
    from: code.length,
  });
  const [clearing, setClearing] = React.useState(false);
  // Resend clock: whole seconds, running from the start when there's a resend, and again after each one.
  const [left, setLeft] = React.useState<number | null>(
    onResend ? resendAfter : null,
  );
  const [resend, setResend] = React.useState<ActionStatus>("idle");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const rowRef = React.useRef<HTMLDivElement>(null);

  // How the new characters arrived: one typed, or several at once (paste, autofill) to cascade in.
  if (arrival.length !== code.length)
    setArrival({ length: code.length, from: arrival.length });
  const arrivedFrom = arrival.from;

  const setCode = (next: string) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const startClock = React.useCallback(
    () => setLeft(resendAfter),
    [resendAfter],
  );
  React.useEffect(() => {
    if (left === null || left <= 0) return;
    const timer = window.setTimeout(
      () => setLeft((s) => (s === null ? s : s - 1)),
      1000,
    );
    return () => window.clearTimeout(timer);
  }, [left]);

  const check = async (full: string) => {
    if (!onComplete) return;
    setPhase("checking");
    let ok = true;
    try {
      ok = (await onComplete(full)) !== false;
    } catch {
      ok = false;
    }
    if (ok) {
      setPhase("right");
      inputRef.current?.blur();
      return;
    }
    setPhase("wrong");
    if (!reduced) {
      rowRef.current?.animate(
        [
          { transform: "none" },
          { transform: "translateX(-5px)" },
          { transform: "translateX(5px)" },
          { transform: "translateX(-3px)" },
          { transform: "none" },
        ],
        { duration: 380, easing: "ease-out" },
      );
    }
    // Let the shake land, then clear from the right and start again at the first box.
    window.setTimeout(
      () => {
        setClearing(true);
        setCode("");
        inputRef.current?.focus();
        window.setTimeout(() => setClearing(false), 400);
      },
      reduced ? 0 : 650,
    );
  };

  const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (phase === "checking" || phase === "right") return;
    const raw = e.target.value;
    const clean = (
      alphanumeric
        ? raw.replace(/[^a-z0-9]/gi, "").toUpperCase()
        : raw.replace(/\D/g, "")
    ).slice(0, length);
    if (phase === "wrong") setPhase("idle");
    setCode(clean);
  };

  // A full code, however it arrived (typed, pasted, autofilled or set from outside), gets checked once.
  const lastLength = React.useRef(code.length);
  React.useEffect(() => {
    if (
      code.length === length &&
      lastLength.current < length &&
      (phase === "idle" || phase === "wrong")
    )
      check(code);
    lastLength.current = code.length;
  }, [code]);

  const doResend = async () => {
    if (!onResend || resend === "pending") return;
    setResend("pending");
    try {
      await onResend();
      setResend("success");
      window.setTimeout(
        () => {
          setResend("idle");
          startClock();
        },
        reduced ? 0 : 1100,
      );
    } catch {
      setResend("error");
    }
  };

  // Where the dashes go between groups.
  const breaks = new Set<number>();
  if (groups)
    groups.reduce((at, size) => (breaks.add(at + size), at + size), 0);
  const right = phase === "right";
  const wrong = phase === "wrong";
  const active =
    focused && phase !== "checking" && !right
      ? Math.min(code.length, length - 1)
      : -1;
  const labelText = right
    ? "Verified"
    : wrong
      ? "That code didn't work"
      : phase === "checking"
        ? "Checking the code"
        : label;

  return (
    <div className={`@container w-full ${className}`} {...props}>
      <label
        htmlFor={id}
        className={`block text-[12.5px] transition-colors duration-300 ${wrong ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
      >
        <TextMorph>{labelText}</TextMorph>
      </label>

      <div className="relative mt-2 w-fit">
        <input
          ref={inputRef}
          id={id}
          value={code}
          onChange={onChange}
          onFocus={(e) => {
            setFocused(true);
            const end = e.currentTarget.value.length;
            e.currentTarget.setSelectionRange(end, end);
          }}
          onBlur={() => setFocused(false)}
          onSelect={(e) => {
            // The caret always sits at the end; the boxes show where you are.
            const el = e.currentTarget;
            if (el.selectionStart !== el.value.length)
              el.setSelectionRange(el.value.length, el.value.length);
          }}
          readOnly={phase === "checking" || right}
          autoFocus={autoFocus}
          autoComplete="one-time-code"
          inputMode={alphanumeric ? "text" : "numeric"}
          pattern={alphanumeric ? "[A-Za-z0-9]*" : "[0-9]*"}
          maxLength={length}
          spellCheck={false}
          aria-invalid={wrong || undefined}
          className="absolute inset-0 z-10 h-full w-full cursor-text bg-transparent text-[16px] text-transparent caret-transparent opacity-0 outline-none [&::selection]:bg-transparent"
        />

        {/* The boxes, and the one pill they become when the code is right. */}
        <div
          ref={rowRef}
          aria-hidden="true"
          className={`relative flex items-center gap-[var(--code-gap,8px)] rounded-[12px] @max-[19rem]:gap-[var(--code-gap,4px)] transition-[box-shadow,background-color] duration-500 ${phase === "checking" ? SHEEN : ""}`}
          style={{
            boxShadow: right
              ? "0 0 0 1px color-mix(in oklab, #10b981 55%, transparent)"
              : "0 0 0 1px transparent",
            background: right
              ? "color-mix(in oklab, #10b981 6%, var(--background))"
              : "transparent",
            transitionTimingFunction: EASE,
          }}
        >
          {Array.from({ length }, (_, i) => {
            const char = code[i];
            const isActive = i === active;
            const cascade =
              !clearing && code.length - arrivedFrom > 1 && i >= arrivedFrom
                ? (i - arrivedFrom) * 45
                : 0;
            const exitDelay = clearing ? (length - 1 - i) * 30 : 0;
            return (
              <React.Fragment key={i}>
                {/* The dash fades but keeps its place, so no digit moves when the code is right. */}
                {breaks.has(i) && i > 0 && (
                  <span
                    className="mx-0.5 block h-px w-2 bg-muted-foreground/40 transition-opacity duration-300"
                    style={{ opacity: right ? 0 : 1 }}
                  />
                )}
                <span
                  className="relative flex h-10 w-[34px] shrink-0 items-center justify-center text-[18px] font-medium tabular-nums text-foreground transition-[box-shadow,background-color] duration-300 @max-[19rem]:w-[30px] @min-[22rem]:h-11 @min-[22rem]:w-9 @min-[22rem]:text-[19px]"
                  style={{
                    borderRadius: 10,
                    boxShadow: right
                      ? "inset 0 0 0 1px transparent"
                      : wrong
                        ? "inset 0 0 0 1px color-mix(in oklab, #ef4444 60%, transparent)"
                        : isActive
                          ? "inset 0 0 0 1.5px color-mix(in oklab, var(--ring) 70%, transparent)"
                          : "inset 0 0 0 1px var(--border)",
                    background: right ? "transparent" : "var(--background)",
                  }}
                >
                  <Glyph
                    char={char}
                    delay={char !== undefined ? cascade : exitDelay}
                    reduced={reduced}
                  />
                  {/* The caret, blinking only in the box you're on. */}
                  {isActive && char === undefined && (
                    <span className="absolute h-5 w-px bg-foreground animate-[ui-blink_1s_steps(1)_infinite] motion-reduce:animate-none" />
                  )}
                </span>
              </React.Fragment>
            );
          })}

          {/* The check at the end of the pill: the pill grows to the right for it, the digits stay put. */}
          <span
            className="grid transition-[grid-template-columns,opacity] duration-500"
            style={{
              gridTemplateColumns: right ? "1fr" : "0fr",
              opacity: right ? 1 : 0,
              transitionTimingFunction: EASE,
            }}
          >
            <span className="flex min-w-0 items-center overflow-hidden">
              <svg
                viewBox="0 0 16 16"
                className="ml-1 mr-3 size-4 shrink-0 text-emerald-600"
                fill="none"
              >
                <path
                  d="M3.5 8.5 6.5 11.5 12.5 4.5"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={1}
                  style={{
                    strokeDashoffset: right ? 0 : 1,
                    transition: reduced
                      ? "none"
                      : `stroke-dashoffset 420ms ${EASE} 260ms`,
                  }}
                />
              </svg>
            </span>
          </span>
        </div>
      </div>

      {onResend && !right && (
        <div className="mt-3 flex h-7 items-center gap-1.5 text-[12px] text-muted-foreground">
          <span>Didn’t get it?</span>
          {/* The countdown and the button share one place; each fades through a blur into the other. */}
          <span className="grid items-center">
            {/* The ticking digits stay out of screen readers; they hear that a resend is coming instead. */}
            <span className="sr-only">
              {left && left > 0 ? "You can resend the code shortly." : ""}
            </span>
            <span
              className="col-start-1 row-start-1 flex items-baseline whitespace-nowrap tabular-nums"
              aria-hidden="true"
              style={{
                opacity: left && left > 0 ? 1 : 0,
                filter: left && left > 0 ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              Resend in 0:
              <NumberRoll
                value={left ?? resendAfter}
                format={{ minimumIntegerDigits: 2 }}
                direction="down"
                duration={700}
              />
            </span>
            <span
              className="col-start-1 row-start-1"
              inert={!!(left && left > 0)}
              style={{
                opacity: left && left > 0 ? 0 : 1,
                filter: left && left > 0 ? "blur(3px)" : "none",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              <StatusButton
                variant="ghost"
                size="sm"
                status={resend}
                labels={{
                  idle: "Resend code",
                  pending: "Sending",
                  success: "Sent",
                  error: "Try again",
                }}
                onClick={doResend}
                className="-ml-2"
              />
            </span>
          </span>
        </div>
      )}

      <p role="status" aria-live="polite" className="sr-only">
        {right
          ? "Code verified"
          : wrong
            ? "That code didn't work. Enter it again."
            : phase === "checking"
              ? "Checking the code"
              : ""}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

"use client";

import * as React from "react";
import { playStrip, preloadStrips } from "./cast-sprite";
import { COO_ART as ART, COO_GEO as G } from "./coo-art";
import { COO_FLY_ART as FLY_ART, COO_FLY_FRAMES as FLY_F } from "./coo-fly-art";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * COO: the carrier pigeon who brings the code
 *
 * An illustrated pigeon on a post, a mailbox across the stage
 * and the route between them, rigged in code:
 *
 *   peck     a nod from his feet for every digit typed
 *   ruffle   a shake of the head when the code is wrong
 *   puff     chest out and two proud flaps when it's right
 *   send     he takes off with an envelope, flies the route to
 *            the mailbox, waits there until the send is done,
 *            pops the flag and flies home empty (real wingbeats,
 *            frames from an animation); if the send
 *            fails he turns back with the envelope still in
 *            his beak
 *   doze     while the resend clock runs he naps on his post:
 *            eye shut, z's drifting up, and a thought bubble over
 *            his head counting the seconds down (`wait`); typing
 *            wakes him, and at zero the bubble pops and he hops
 *
 * The scene is drawn at 364 × 176 and scaled to the stage.
 * One frame loop outside React moves him and sleeps when
 * he's still; flaps swap between two drawn wing poses.
 * ───────────────────────────────────────────────────────── */

export interface CooHandle {
  peck: () => void;
  ruffle: () => void;
  puff: () => void;
  /** Take off with a new code; call `delivered` when the send settles. */
  send: () => void;
  /** The send settled: he pops the flag (ok) or brings the envelope back, then lands and calls onHome. */
  delivered: (ok: boolean, onHome: () => void) => void;
}

const W = 364;
const H = 176;
const KB = 0.42; // the pigeon's drawing scale
/* His wingbeats: frames cut from an animation, placed by his cap like the standing art.
 * In the clips (960px square) his cap is at (611, 440) and the frames cover (174, 210)–(786, 906). */
const FS = 0.143;
const FLYBOX = {
  left: (174 - 611) * FS,
  top: (210 - 440) * FS,
  w: (786 - 174) * FS,
  h: (906 - 210) * FS,
};
type FlyClip = keyof typeof FLY_F.clips;
const KP = 0.62; // the props'
const POST = { x: 72, foot: 180 };
const BOX = { x: 300, foot: 180 };
const FEET = { x: POST.x, y: POST.foot - G.post.h * KP + 1.5 };
/** Where his cap is when he stands on the post, and while he waits over the mailbox. */
const HOME = {
  x: FEET.x + (G.stand.cap.x - G.stand.feet.x) * KB,
  y: FEET.y + (G.stand.cap.y - G.stand.feet.y) * KB,
};
const OVER = { x: BOX.x + 4, y: 40 };
const CTRL = { x: 192, y: 40 };
/** The route drawn between them: from his beak to the mailbox door. */
const BEAK = {
  x: FEET.x + (184 - G.stand.feet.x) * KB,
  y: FEET.y + (50 - G.stand.feet.y) * KB,
};
export const COO_ROUTE = `M${BEAK.x.toFixed(1)} ${BEAK.y.toFixed(1)} Q${(W / 2 + 14).toFixed(1)} 2 ${BOX.x - 6} 82`;
const FLY = 1050; // ms each way
const FLAP = 95; // ms a wing pose is held

const clamp = (v: number, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const inOut = (k: number) =>
  k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;

type Spring = { x: number; v: number };
function step(s: Spring, target: number, dt: number, k = 260, c = 18) {
  s.v += ((target - s.x) * k - s.v * c) * dt;
  s.x += s.v * dt;
  if (Math.abs(target - s.x) < 1e-3 && Math.abs(s.v) < 1e-3) {
    s.x = target;
    s.v = 0;
    return true;
  }
  return false;
}

type Flight = {
  leg: "out" | "wait" | "back";
  t0: number;
  carrying: boolean;
  ok?: boolean;
  onHome?: () => void;
  popAt?: number;
};

export class CooEngine {
  parts: Record<string, Element | null> = {};
  reduced = false;
  rot: Spring = { x: 0, v: 0 };
  puffS: Spring = { x: 0, v: 0 };
  hop: Spring = { x: 0, v: 0 };
  wobble: Spring = { x: 0, v: 0 };
  lid: Spring = { x: 0, v: 0 };
  dozing = false;
  zTimer = 0;
  flagUp = true;
  puffT = 0;
  flapUntil = 0;
  flying: FlyClip | null = null;
  blinkAt = 0;
  flight: Flight | null = null;
  raf = 0;
  last = 0;
  seq = 0;
  blinkTimer = 0;
  observer: ResizeObserver | null = null;
  frame = (now: number) => this.tick(now);

  part = (name: string) => (el: Element | null) => {
    this.parts[name] = el;
  };

  mount(reduced: boolean) {
    this.reduced = reduced;
    const host = this.parts.host as HTMLElement | null;
    const scene = this.parts.scene as HTMLElement | null;
    if (host && scene) {
      const fit = () =>
        scene.style.setProperty("transform", `scale(${host.clientWidth / W})`);
      fit();
      this.observer = new ResizeObserver(fit);
      this.observer.observe(host);
    }
    if (!reduced) {
      (this.parts.stand as HTMLElement | null)?.animate(
        [{ transform: "none" }, { transform: "scale(1.012, 1.022)" }],
        {
          duration: 1600,
          iterations: Infinity,
          direction: "alternate",
          easing: "ease-in-out",
        },
      );
    }
    preloadStrips(Object.values(FLY_ART));
    this.draw(performance.now());
    this.scheduleBlink();
  }

  destroy() {
    cancelAnimationFrame(this.raf);
    window.clearTimeout(this.blinkTimer);
    window.clearTimeout(this.zTimer);
    this.raf = 0;
    this.observer?.disconnect();
    this.observer = null;
    (this.parts.stand as HTMLElement | null)
      ?.getAnimations()
      .forEach((a) => a.cancel());
    (this.parts.fly as HTMLElement | null)
      ?.getAnimations()
      .forEach((a) => a.cancel());
    this.flying = null;
  }

  scheduleBlink() {
    window.clearTimeout(this.blinkTimer);
    this.blinkTimer = window.setTimeout(
      () => {
        this.blinkAt = performance.now();
        this.seq++;
        this.wake();
        this.scheduleBlink();
      },
      2400 + ((this.seq * 1531 + 377) % 3600),
    );
  }

  wake() {
    if (this.raf || !this.parts.bird) return;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.frame);
  }

  /** Nap (eye shut, z's) or wake; waking because the wait is over gives a little hop. */
  doze(on: boolean, hop = false) {
    if (on === this.dozing) return;
    this.dozing = on;
    window.clearTimeout(this.zTimer);
    if (on) this.zTimer = window.setTimeout(() => this.snore(), 500);
    else if (hop && !this.reduced) {
      this.hop.v -= 120;
      this.rot.v -= 140;
    }
    if (this.reduced) {
      this.lid.x = on ? 1 : 0;
      this.draw(performance.now());
      return;
    }
    this.wake();
  }

  /** A "z" drifts up from his head and fades; another follows while he sleeps. */
  snore() {
    const layer = this.parts.zs as HTMLElement | null;
    if (!this.dozing || this.reduced || !layer) return;
    if (!this.flight) {
      const z = document.createElement("span");
      const big = this.seq++ % 2 === 0;
      z.textContent = "z";
      z.style.cssText = `position:absolute;left:${HOME.x + 8}px;top:${HOME.y - 6}px;font-size:${big ? 15 : 11}px;font-weight:600;line-height:1;color:var(--coo-z);opacity:0`;
      layer.appendChild(z);
      z.animate(
        [
          {
            opacity: 0,
            transform: "translate(0, 0) scale(0.6) rotate(-10deg)",
          },
          { opacity: 1, offset: 0.25 },
          {
            opacity: 0,
            transform: `translate(${big ? -20 : -12}px, -24px) scale(1.1) rotate(-14deg)`,
          },
        ],
        { duration: 2200, easing: "cubic-bezier(0.22, 1, 0.36, 1)" },
      ).onfinish = () => z.remove();
    }
    this.zTimer = window.setTimeout(() => this.snore(), 1100);
  }

  peck() {
    if (this.reduced || this.flight) return;
    this.rot.v += 240;
    this.wake();
  }

  ruffle() {
    if (this.reduced || this.flight) return;
    this.rot.v -= 420;
    this.wobble.v += 9;
    this.wake();
  }

  puff() {
    this.puffT = 1;
    if (this.reduced) {
      this.puffS.x = 1;
      this.draw(performance.now());
      return;
    }
    this.flapUntil = performance.now() + 4 * FLAP;
    this.hop.v -= 150;
    this.wake();
  }

  send() {
    this.puffT = 0;
    if (this.reduced) {
      this.flight = { leg: "wait", t0: performance.now(), carrying: true };
      this.draw(performance.now());
      return;
    }
    this.flight = { leg: "out", t0: performance.now(), carrying: true };
    this.wake();
  }

  delivered(ok: boolean, onHome: () => void) {
    const f = this.flight;
    if (!f) {
      onHome();
      return;
    }
    f.ok = ok;
    f.onHome = onHome;
    if (this.reduced) {
      this.flight = null;
      if (ok) this.flagUp = true;
      this.draw(performance.now());
      onHome();
      return;
    }
    this.wake();
  }

  tick(now: number) {
    const dt = Math.min(0.05, (now - this.last) / 1000);
    this.last = now;
    let busy = false;
    const f = this.flight;
    if (f) {
      busy = true;
      const t = now - f.t0;
      if (f.leg === "out" && t >= FLY) {
        f.leg = "wait";
        f.t0 = now;
      } else if (f.leg === "wait" && f.ok !== undefined) {
        if (f.ok && f.popAt === undefined) {
          // a new letter: the flag drops, then springs back up
          f.popAt = now;
          this.flagUp = false;
          this.wobble.v -= 6;
        }
        if (
          f.popAt !== undefined &&
          this.flagUp === false &&
          now - f.popAt > 260
        ) {
          this.flagUp = true;
          this.wobble.v += 10;
        }
        if (!f.ok || now - (f.popAt ?? now) > 620) {
          f.leg = "back";
          f.t0 = now;
          f.carrying = !f.ok;
        }
      } else if (f.leg === "back" && t >= FLY) {
        this.flight = null;
        this.hop.v += 90;
        this.rot.v -= 60;
        f.onHome?.();
      }
    }
    const settled = [
      step(this.rot, 0, dt, 300, 16),
      step(this.puffS, this.puffT, dt, 200, 16),
      step(this.hop, 0, dt, 320, 15),
      step(this.wobble, 0, dt, 260, 9),
      step(this.lid, this.dozing && !this.flight ? 1 : 0, dt, 120, 18),
    ].every(Boolean);
    if (!settled || now < this.flapUntil) busy = true;
    if (this.blinkAt && now - this.blinkAt < 170) busy = true;
    else this.blinkAt = 0;
    this.draw(now);
    this.raf = busy ? requestAnimationFrame(this.frame) : 0;
  }

  show(name: "stand" | FlyClip) {
    (this.parts.stand as HTMLElement | null)?.style.setProperty(
      "opacity",
      name === "stand" ? "1" : "0",
    );
    const sprite = this.parts.fly as HTMLElement | null;
    sprite?.style.setProperty("opacity", name === "stand" ? "0" : "1");
    const clip = name === "stand" ? null : name;
    if (clip && clip !== this.flying) {
      playStrip(sprite, {
        src: FLY_ART[clip],
        frames: FLY_F.clips[clip].frames,
        fps: FLY_F.clips[clip].fps,
        size: FLYBOX.w,
        height: FLYBOX.h,
        reduced: this.reduced,
      });
    }
    if (!clip) sprite?.getAnimations().forEach((a) => a.cancel());
    this.flying = clip;
  }

  draw(now: number) {
    const bird = this.parts.bird as HTMLElement | null;
    if (!bird) return;
    const f = this.flight;
    let x = HOME.x;
    let y = HOME.y;
    let angle = 0;
    let flip = 1;
    let frame: "stand" | FlyClip = "stand";
    if (f) {
      const t = now - f.t0;
      const k =
        f.leg === "out"
          ? inOut(clamp(t / FLY))
          : f.leg === "back"
            ? 1 - inOut(clamp(t / FLY))
            : 1;
      // along the arc from home to over the mailbox (and back the same way)
      x =
        (1 - k) * (1 - k) * HOME.x + 2 * (1 - k) * k * CTRL.x + k * k * OVER.x;
      y =
        (1 - k) * (1 - k) * HOME.y + 2 * (1 - k) * k * CTRL.y + k * k * OVER.y;
      y += Math.sin((t / FLAP) * Math.PI) * 1.6;
      flip = f.leg === "back" ? -1 : 1;
      angle =
        f.leg === "wait"
          ? 0
          : (f.leg === "out" ? 1 : -1) * 6 * Math.sin(Math.PI * clamp(t / FLY));
      const empty = !f.carrying;
      frame = empty ? "flyEmpty" : "fly";
    } else if (now < this.flapUntil) {
      frame = "flyEmpty";
    }
    this.show(frame);
    const puff = 1 + 0.07 * clamp(this.puffS.x, 0, 1.4);
    const fx = (G.stand.feet.x - G.stand.cap.x) * KB;
    const fy = (G.stand.feet.y - G.stand.cap.y) * KB;
    // standing, he turns and swells about his feet; flying, about his middle
    bird.style.transform =
      `translate(${x.toFixed(2)}px, ${(y + this.hop.x * 0.06).toFixed(2)}px) scale(${flip}, 1) ` +
      (f
        ? `rotate(${angle.toFixed(2)}deg)`
        : `translate(${fx.toFixed(2)}px, ${fy.toFixed(2)}px) rotate(${(this.rot.x * 0.05).toFixed(2)}deg) scale(${puff.toFixed(4)}) translate(${(-fx).toFixed(2)}px, ${(-fy).toFixed(2)}px)`);

    // the mailbox: which flag, and a little rock when it changes
    (this.parts.box as HTMLElement | null)?.style.setProperty(
      "opacity",
      this.flagUp ? "0" : "1",
    );
    (this.parts.boxFlag as HTMLElement | null)?.style.setProperty(
      "opacity",
      this.flagUp ? "1" : "0",
    );
    (this.parts.mailbox as HTMLElement | null)?.style.setProperty(
      "transform",
      `rotate(${(this.wobble.x * 0.25).toFixed(2)}deg)`,
    );

    const blink =
      this.blinkAt && frame === "stand"
        ? Math.sin(clamp((now - this.blinkAt) / 160) * Math.PI)
        : 0;
    const shut = frame === "stand" ? Math.max(blink, clamp(this.lid.x)) : 0;
    (this.parts.lid as SVGElement | null)?.setAttribute(
      "transform",
      `translate(${G.stand.eye.x} ${G.stand.eye.y - G.stand.eye.r}) scale(1 ${shut.toFixed(3)})`,
    );
  }
}

export function Coo({
  wait,
  dozing = false,
  reduced,
  ref,
  className = "",
}: {
  /** Seconds left before he can fly again; 0 when he can. */
  wait: number;
  /** Napping through the wait (the block wakes him while you type). */
  dozing?: boolean;
  reduced: boolean;
  ref?: React.Ref<CooHandle>;
  className?: string;
}) {
  const [engine] = React.useState(() => new CooEngine());
  const [waited, setWaited] = React.useState(wait);
  // the clock reaching zero (not a first render at zero) wakes him with a hop
  const [woke, setWoke] = React.useState(false);
  if (waited !== wait) {
    setWaited(wait);
    setWoke(waited > 0 && wait <= 0);
  }

  React.useLayoutEffect(() => {
    engine.mount(reduced);
    return () => engine.destroy();
  }, [engine, reduced]);

  React.useEffect(() => {
    engine.doze(dozing && wait > 0, woke);
  }, [engine, dozing, wait, woke]);

  React.useImperativeHandle(
    ref,
    () => ({
      peck: () => engine.peck(),
      ruffle: () => engine.ruffle(),
      puff: () => engine.puff(),
      send: () => engine.send(),
      delivered: (ok, onHome) => engine.delivered(ok, onHome),
    }),
    [engine],
  );

  const img = "pointer-events-none absolute max-w-none select-none";
  const frame = (
    name: "stand",
    src: string,
    k: number,
    part: string,
    shown: boolean,
  ) => {
    const g = G[name];
    return (
      <img
        ref={engine.part(part)}
        src={src}
        alt=""
        draggable={false}
        className={img}
        style={{
          left: -g.cap.x * k,
          top: -g.cap.y * k,
          width: g.w * k,
          height: g.h * k,
          opacity: shown ? 1 : 0,
          transformOrigin:
            name === "stand"
              ? `${G.stand.feet.x * k}px ${G.stand.feet.y * k}px`
              : undefined,
        }}
      />
    );
  };
  return (
    <div
      ref={engine.part("host")}
      aria-hidden="true"
      className={`relative w-full ${className}`}
      style={{ aspectRatio: `${W} / ${H}` }}
    >
      <div
        ref={engine.part("scene")}
        className="absolute left-0 top-0 origin-top-left"
        style={{ width: W, height: H }}
      >
        {/* the route he flies */}
        <svg
          viewBox={`0 0 ${W} ${H}`}
          className="absolute inset-0 size-full overflow-visible"
          fill="none"
        >
          <path
            d={COO_ROUTE}
            stroke="var(--coo-route)"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeDasharray="2 5"
            opacity="0.4"
          />
        </svg>

        <img
          src={ART.post}
          alt=""
          draggable={false}
          className={img}
          style={{
            left: POST.x - (G.post.w * KP) / 2,
            top: POST.foot - G.post.h * KP,
            width: G.post.w * KP,
            height: G.post.h * KP,
          }}
        />
        <div
          ref={engine.part("mailbox")}
          className="absolute left-0 top-0 size-full"
