        <div
          ref={engine.part("bird")}
          className="absolute left-0 top-0 will-change-transform"
        >
          {frame("stand", ART.stand, KB, "stand", true)}
          <div
            ref={engine.part("fly")}
            className="absolute"
            style={{
              left: FLYBOX.left,
              top: FLYBOX.top,
              width: FLYBOX.w,
              height: FLYBOX.h,
